// Layout + terrain for the hilly forest (wave mode). Pure maths (no three.js). 180 x 120 (smaller than the old 240 x 160).
// Three dense woods, open meadows, four IRREGULAR lakes (two of them rocky, with boulders standing in the water) and winding dirt lanes. You start in a clearing in the middle.
// The terrain is generated by world/mapWorld.js, the same world shape worldGen.js makes, so worldMap.js can draw it. Export names are the same as before.
import {makeWorld,rockFormations,lakeRocks,lakeIndexAt,sstep} from './world/mapWorld.js';
import {FOREST,STONE,pathD as lanePathD,PATH_GLSL as lanePathGLSL} from './world/biomes.js';

export const W=180,H=120,HW=W/2,HH=H/2;
export const SPAWN={x:0,z:0};
export const FORESTS=[[-44,-24,28],[42,28,28],[-4,40,18]];                      // dense woods: [x, z, radius]
const LAKES=[[-33,26,10,1],[40,-26,8,1],[6,-40,5.5],[62,8,4.5]];                // [x, z, size, rocky]  (the outline is noisy and stretched, size is the average radius)
export const ROCKY=[0,1];                                                      // lakes with boulders standing in the water
export const pathD=lanePathD,PATH_GLSL=lanePathGLSL;                           // dirt lanes (same formula as the ground shader)
/** 0..1: how deep inside a dense forest this point is */
export function forestW(x,z){let w=0;for(const f of FORESTS)w=Math.max(w,1-sstep(f[2]*.45,f[2],Math.hypot(x-f[0],z-f[1])));return w}

const KEEP=[[SPAWN.x,SPAWN.z,9]];
export const WORLD=makeWorld({
  seed:7,W,H,margin:40,pad:26,spawn:SPAWN,rise:4,
  height:(x,z,n)=>(n.fbm(x*.017+11.3,z*.017+4.7)-.47)*14+Math.sin(x*.04+.6)*Math.cos(z*.05+.3)*2.2,
  flats:[{x:0,z:0,r1:8,r2:22}],keep:KEEP,
  lakes:LAKES,
  // forest everywhere, stone (grey ground, boulders, pines) around the rocky lakes
  biomes:(x,z,n,w)=>{let st=0;const wx=(n.fbm(x*.05,z*.05,2)-.5)*9,wz=(n.fbm(x*.05+9,z*.05,2)-.5)*9;
    for(const [cx,cz,r,rk] of LAKES)if(rk)st=Math.max(st,1-sstep(r+3,r+15,Math.hypot(x-cx+wx,z-cz+wz)));
    st*=.9;w[FOREST]=1-st;w[STONE]=st},
  scatterMul:(x,z)=>.5+1.4*forestW(x,z),                                          // meadows are airy, the woods are packed
  mul:{rock:.8},
  decor:(w,R)=>{const f=rockFormations(w,R,{count:3,size:.9,moss:true,avoid:KEEP,lane:lanePathD});
    return{rocks:[...lakeRocks(w,R,KEEP),...f.rocks],keep:f.zones}}
});

export const PONDS=WORLD.lakes.map(l=>[l.x,l.z,l.r]);                           // [x, z, average radius]
export const PONDL=WORLD.lakes.map(l=>l.L);
export const GRID={x0:WORLD.x0,z0:WORLD.z0,nx:WORLD.nx,nz:WORLD.nz,gs:1,data:WORLD.terr,margin:WORLD.margin};
export const terrainAt=(x,z)=>WORLD.terrainAt(x,z);      // the actual ground surface (mesh, trees, grass)
export const heightAt=(x,z)=>WORLD.heightAt(x,z);        // the surface the player, enemies and bullets use (water is wadeable)
export const waterAt=(x,z)=>lakeIndexAt(WORLD,x,z);      // index of the lake under (x,z), or -1
export const slopeAt=(x,z,e=1.2)=>Math.hypot(heightAt(x+e,z)-heightAt(x-e,z),heightAt(x,z+e)-heightAt(x,z-e))/(2*e);